def has_path(n, edges, start, end):
    """
    Determine if there exists a path between two nodes using Depth-First Search (DFS) algorithm.

    :param n: An integer representing the number of nodes.
    :param edges: A list of tuples (u, v), where 'u' is the starting node, and 'v' is the ending node of a directed edge.
    :param start: The starting node from which to search (integer).
    :param end: The ending node that we want to reach (integer).
    :return: A boolean value, True if there is a path from `start` to `end`, False otherwise.
    """

    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)

    stack = [start]
    visited = set()

    while stack:
        node = stack.pop()
        if node == end:
            return True
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    stack.append(neighbor)

    return False

